/*
 * A379374  Irregular triangle read by rows in which row n lists the divisors
 *          of n except the divisors "e" described in A005279.
 * https://oeis.org/A379374
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   row m lists the divisors e of m, in increasing order, except
 *            those with a divisor j of m such that j < e < 2*j. Rows are
 *            generated by trial division and cached
 * Range:     u8 n <= 82, u16 n <= 82, u32 n <= 82, u64 n <= 82, u128 n <= 82,
 *            big any n
 * Validated: partial, pass, 82 terms through n = 82 (2026-11-10)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

static uint64_t *g_vals = NULL;
static uint64_t g_len = 0, g_cap = 0, g_row = 0;

static void A379374_push(uint64_t v) {
    if (g_len >= g_cap) {
        g_cap = g_cap ? g_cap * 2 : 256;
        g_vals = (uint64_t *)realloc(g_vals, g_cap * sizeof(uint64_t));
        if (!g_vals) abort();
    }
    g_vals[g_len++] = v;
}

static void A379374_row(uint64_t m) {
    uint64_t divs[4096];
    size_t c = 0;
    for (uint64_t i = 1; i <= m / i; i++) {
        if (m % i == 0) {
            divs[c++] = i;
            if (i != m / i) divs[c++] = m / i;
        }
    }
    for (size_t i = 1; i < c; i++) {
        uint64_t v = divs[i];
        size_t j = i;
        while (j > 0 && divs[j - 1] > v) { divs[j] = divs[j - 1]; j--; }
        divs[j] = v;
    }
    for (size_t i = 0; i < c; i++) {
        if (i > 0 && 2 * divs[i - 1] > divs[i]) continue;
        A379374_push(divs[i]);
    }
}

seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;
    while (g_len < (uint64_t)n) {
        g_row++;
        A379374_row(g_row);
    }
    return (seq_t)g_vals[n - 1];
}
